output_text:
[
  {
    "id": "no_cart_in_single_file_aisles",
    "text": "Shopping carts must not be pushed into single-file shelf aisles where shelves border both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "park_before_entering_single_file",
    "text": "Before entering a single-file shelf aisle, the shopper must leave the cart outside rather than enter while still holding it.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "retrieve_cart_after_narrow_aisle",
    "text": "After returning from a single-file shelf aisle to the cart-parking bay, the shopper must retrieve the cart before continuing.",
    "abstraction": {
      "state_properties": {
        "cartParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartlessParkingBay": {
          "and": [
            "cartParkingBay",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "returnToParkingBayWithoutCart": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              "S",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "cartlessParkingBay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "returnToParkingBayWithoutCart",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_cartless_open_store_travel",
    "text": "Walking without a cart is allowed only in the entrance/cart area or in the narrow-aisle cart-free zone, not through ordinary open store space.",
    "abstraction": {
      "state_properties": {
        "entranceCartArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartFreeZone": {
          "or": [
            "entranceCartArea",
            "cartParkingBay",
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartFreeZone"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_wide_shelf_service",
    "text": "Shelf interactions from a wide aisle require the shopper to have the cart, while narrow-aisle shelf interactions may be done on foot.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "wideShelfFace": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            },
            {
              "ge": [
                "freeWidthH",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "wideShelfFace",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "drop_cart_only_at_parking_bays",
    "text": "A shopper may put down the cart only at designated wide parking bays that serve the single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "cartParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "cartParkingBay"
          }
        ]
      }
    }
  },
  {
    "id": "service_narrow_aisle_once_entered",
    "text": "If the shopper enters a single-file shelf aisle on foot, they are expected to perform the shelf interaction there before abandoning that detour.",
    "abstraction": {
      "state_properties": {
        "cartParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileOnFoot": {
          "pre": {
            "and": [
              "cartParkingBay",
              "N",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "singleFileShelfAisle"
        },
        "narrowAisleShelfService": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileOnFoot",
      "discharge": "narrowAisleShelfService"
    }
  },
  {
    "id": "leave_lower_shelf_service_flow",
    "text": "After collecting from a lower wide-aisle shelf face, the shopper should rejoin traffic by moving south or east rather than treating every visit to that cell as requiring a south exit.",
    "abstraction": {
      "state_properties": {
        "lowerWideShelfFace": {
          "and": [
            "adjShelf",
            "shelfN",
            {
              "le": [
                "freeWidthV",
                2
              ]
            },
            {
              "ge": [
                "freeWidthH",
                2
              ]
            }
          ]
        }
      },
      "events": {
        "lowerWideShelfPickup": {
          "pre": {
            "and": [
              "lowerWideShelfFace",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "lowerWideShelfPickup",
      "discharge": {
        "or": [
          "S",
          "E"
        ]
      }
    }
  }
]
